      "content": "{\n  \"name\": \"@xmanrui/dsh-im\",\n  \"version\": \"5.10.0\",\n  \"icon\": \"./assets/logo-plugin-message-link-gradient.webp\",\n  \"description\": \"把微信、飞书、企微、钉钉、QQ、Telegram、WhatsApp、Slack、Discord、Matrix接入DSH。 Connect Telegram, WhatsApp, Slack, Discord, Matrix, WeChat, Feishu, WeCom, DingTalk, and QQ to DSH.\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"ai-agent\",\n    \"im\",\n    \"instant-messaging\",\n    \"chatbot\",\n    \"feishu\",\n    \"lark\",\n    \"wechat\",\n    \"wecom\",\n    \"dingtalk\",\n    \"qq\",\n    \"slack\",\n    \"telegram\",\n    \"discord\",\n    \"whatsapp\",\n    \"imessage\",\n    \"matrix\",\n    \"ai-office\"\n  ],\n  \"author\": \"xmanrui (https://github.com/xmanrui)\",\n  \"license\": \"MIT\",\n  \"type\": \"module\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/xmanrui/dsh-im.git\"\n  },\n  \"homepage\": \"https://github.com/xmanrui/dsh-im#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/xmanrui/dsh-im/issues\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"bin\": {\n    \"dsh-im\": \"bin/dsh-im.mjs\"\n  },\n  \"main\": \"./lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"files\": [\n    \"assets\",\n    \"bin\",\n    \"cordis.patch.yml\",\n    \"lib\",\n    \"locale/*.json\",\n    \"plugin-src\",\n    \"scripts/telegram-menu-scopes.mjs\",\n    \"scripts/verify-interface-language.mjs\",\n    \"scripts/verify-injected-context.mjs\",\n    \"scripts/verify-lan-management.mjs\",\n    \"scripts/verify-model-setting.mjs\",\n    \"scripts/verify-package.mjs\",\n    \"scripts/verify-session-channel-logos.mjs\",\n    \"scripts/verify-session-title-prefix.mjs\",\n    \"src\",\n    \"PROACTIVE_DELIVERY.md\",\n    \"PROACTIVE_DELIVERY.en.md\",\n    \"docs/client-integration.md\",\n    \"docs/preset-workspaces.md\",\n    \"LICENSE\",\n    \"README.md\",\n    \"README.en.md\",\n    \"THIRD_PARTY_NOTICES.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-locale\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"compatibility\": {\n      \"dsh\": \"0.2.1-rc.2\",\n      \"dshReleases\": {\n        \"0.2.0-rc.2\": \"compatible\",\n        \"0.2.1-rc.2\": \"compatible\"\n      },\n      \"profiles\": [\n        \"web\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node plugin-src/client/build.mjs && node plugin-src/host/build.mjs\",\n    \"test\": \"node --test test/*.test.mjs test/channels/*/*.test.mjs\",\n    \"check\": \"npm run build && npm test && node scripts/verify-package.mjs\"\n  },\n  \"engines\": {\n    \"node\": \">=22.19\"\n  },\n  \"dependencies\": {\n    \"@matrix-org/olm\": \"3.2.15\",\n    \"@tencent-connect/qqbot-connector\": \"1.2.0\",\n    \"@tencent-connect/qqbot-nodejs\": \"1.0.4\",\n    \"@wecom/aibot-node-sdk\": \"1.0.7\",\n    \"dingtalk-stream\": \"2.1.4\",\n    \"imapflow\": \"^2.0.5\",\n    \"mailparser\": \"^3.9.43\",\n    \"nodemailer\": \"^10.1.4\",\n    \"qrcode\": \"1.5.4\",\n    \"undici\": \"7.30.1\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.1\",\n    \"@larksuiteoapi/node-sdk\": \"1.73.0\",\n    \"@whiskeysockets/baileys\": \"7.0.0-rc14\",\n    \"esbuild\": \"0.25.9\",\n    \"https-proxy-agent\": \"5.0.1\",\n    \"react\": \"18.3.1\",\n    \"react-dom\": \"18.3.1\",\n    \"react-test-renderer\": \"18.3.1\",\n    \"semver\": \"7.8.5\"\n  },\n  \"directories\": {\n    \"doc\": \"docs\",\n    \"lib\": \"lib\",\n    \"test\": \"test\"\n  },\n  \"optionalDependencies\": {\n    \"@tencent-qqmail/agently-cli\": \"^1.0.18\",\n    \"sharp\": \"0.35.5\"\n  }\n}\n"
