      "path": "plugin-src/host/index.mjs",
      "content": "import { installGroupHistoryTools } from '../../src/channels/shared/group-history-access.mjs';\nimport { apply as applyDingtalk } from './channels/dingtalk/index.mjs';\nimport { apply as applyDiscord } from './channels/discord/index.mjs';\nimport { apply as applyOffice } from './channels/office/index.mjs';\nimport { apply as applyFeishu } from './channels/feishu/index.mjs';\nimport { apply as applyQq } from './channels/qq/index.mjs';\nimport { apply as applySlack } from './channels/slack/index.mjs';\nimport { apply as applyTelegram } from './channels/telegram/index.mjs';\nimport { apply as applyWecom } from './channels/wecom/index.mjs';\nimport { apply as applyWecomApp } from './channels/wecom-app/index.mjs';\nimport { apply as applyWeixin } from './channels/weixin/index.mjs';\nimport { apply as applyWhatsapp } from './channels/whatsapp/index.mjs';\nimport { apply as applyIMessage } from './channels/imessage/index.mjs';\nimport { apply as applyEmail } from './channels/email/index.mjs';\nimport { apply as applyMatrix } from './channels/matrix/index.mjs';\nimport { installOutboundArtifactTool } from '../../src/channels/shared/semantic/artifact.mjs';\nimport { installHostLanguage } from './host-language.mjs';\nimport { installHostLanguageRpc } from './host-language-rpc.mjs';\nimport { installDeliveryRpc } from './delivery-rpc.mjs';\nimport { installDeliveryHttp } from './delivery-http.mjs';\nimport { createDeliveryService } from './delivery-service.mjs';\nimport { createDsBotClient } from './ds-bot-client.mjs';\nimport { installDsBotQuestionSync } from './ds-bot-question-sync.mjs';\nimport { installInboundTtlRpc } from './inbound-ttl-rpc.mjs';\nimport { installDeliverySyncRpc } from './delivery-sync-rpc.mjs';\nimport { installSidebarSettingsRpc } from './sidebar-settings.mjs';\nimport { installInjectedContext } from './injected-context.mjs';\nimport { installSessionSyncCoordinator } from './session-sync-coordinator.mjs';\nimport { deliverySwitchesOff } from '../../src/channels/shared/delivery-sync-settings.mjs';\nimport { getDeliverySyncSettingsStore } from '../../src/channels/shared/delivery-sync-settings-store.mjs';\nimport { installSessionTitlePrefix } from './session-title-prefix.mjs';\nimport { installUpdateRpc } from './update-rpc.mjs';\nimport { installChannelListRpc } from './channel-list-rpc.mjs';\n\nexport const name = 'dsh-im-host';\nexport const inject = [\n  'connection',\n  'credentials',\n  'typertGateway',\n];\n\nfunction channelConfig(config, name, deliveryService) {\n  const channel = {\n    ...(config.dshHome ? { dshHome: config.dshHome } : {}),\n    ...(config.groupByAgentPreset === undefined ? {} : { groupByAgentPreset: config.groupByAgentPreset }),\n    ...config[name],\n  };\n  const withAuthority = config.rpcAuthority === undefined\n    ? channel\n    : { ...channel, rpcAuthority: config.rpcAuthority };\n  return name === 'office' ? withAuthority : { ...withAuthority, deliveryService };\n}\n\nexport function createImHostPlugin(internals = {}) {\n  const startHostLanguage = internals.installHostLanguage ?? installHostLanguage;\n  const startHostLanguageRpc = internals.installHostLanguageRpc ?? installHostLanguageRpc;\n  const startUpdate = internals.installUpdateRpc ?? installUpdateRpc;\n  const startInboundTtl = internals.installInboundTtlRpc ?? installInboundTtlRpc;\n  const startDeliverySync = internals.installDeliverySyncRpc ?? installDeliverySyncRpc;\n  const startSidebarSettings = internals.installSidebarSettingsRpc ?? installSidebarSettingsRpc;\n  const startInjectedContext = internals.installInjectedContext ?? installInjectedContext;\n  const startDelivery = internals.installDeliveryRpc ?? installDeliveryRpc;\n  const startDeliveryHttp = internals.installDeliveryHttp ?? installDeliveryHttp;\n  const startSessionSync = internals.installSessionSyncCoordinator\n    ?? installSessionSyncCoordinator;\n  const makeDeliveryService = internals.createDeliveryService ?? createDeliveryService;\n  const startFeishu = internals.applyFeishu ?? applyFeishu;\n  const startWeixin = internals.applyWeixin ?? applyWeixin;\n  const startDingtalk = internals.applyDingtalk ?? applyDingtalk;\n  const startWecom = internals.applyWecom ?? applyWecom;\n  const startWecomApp = internals.applyWecomApp ?? applyWecomApp;\n  const startQq = internals.applyQq ?? applyQq;\n  const startSlack = internals.applySlack ?? applySlack;\n  const startTelegram = internals.applyTelegram ?? applyTelegram;\n  const startDiscord = internals.applyDiscord ?? applyDiscord;\n  const startOffice = internals.applyOffice ?? applyOffice;\n  const startWhatsapp = internals.applyWhatsapp ?? applyWhatsapp;\n  const startIMessage = internals.applyIMessage ?? applyIMessage;\n  const startEmail = internals.applyEmail ?? applyEmail;\n  const startMatrix = internals.applyMatrix ?? applyMatrix;\n  const channels = [\n    ['feishu', startFeishu],\n    ['weixin', startWeixin],\n    ['dingtalk', startDingtalk],\n    ['wecom', startWecom],\n    ['wecomApp', startWecomApp],\n    ['qq', startQq],\n    ['slack', startSlack],\n    ['telegram', startTelegram],\n    ['discord', startDiscord],\n    ['whatsapp', startWhatsapp],\n    ['imessage', startIMessage],\n    ['email', startEmail],\n    ['matrix', startMatrix],\n    ['office', startOffice],\n  ];\n  return Object.freeze({\n    name,\n    inject,\n    async apply(ctx, config = {}) {\n      const unavailableSessionSyncChannels = channels\n        .map(([channel]) => channel)\n        .filter((channel) => channel !== 'office'\n          && config[channel]?.harnessBaseUrl !== undefined);\n      const deliveryService = makeDeliveryService({\n        unavailableSessionSyncChannels: unavailableSessionSyncChannels.map((channel) => channel === 'wecomApp' ? 'wecom-app' : channel),\n        dsBot: createDsBotClient(ctx),\n      });\n      // The delivery switches are the master for everything that follows a Session\n      // through its targets: with both off, `listSessionSyncTargets` answers empty,\n      // so neither the coordinator nor a channel's own mirror (Feishu card) sends.\n      // A settings read failure must not disable delivery, so it falls through.\n      if (typeof deliveryService.listSessionSyncTargets === 'function') {\n        const rawListSessionSyncTargets = deliveryService.listSessionSyncTargets.bind(deliveryService);\n        deliveryService.listSessionSyncTargets = async (sessionId) => {\n          try {\n            if (deliverySwitchesOff(await getDeliverySyncSettingsStore(config).get())) return [];\n          } catch {\n            // keep the unwrapped behaviour\n          }\n          return rawListSessionSyncTargets(sessionId);\n        };\n      }\n      /** Sessions already reported, so the log stays one line per session. */\n      const describedSessions = new Set();\n      const describeConversationLogged = async (sessionId) => {\n        const described = await deliveryService.describeConversation(sessionId);\n        if (described && !describedSessions.has(sessionId)) {\n          describedSessions.add(sessionId);\n          const log = typeof ctx?.logger === 'function' ? ctx.logger(name) : (ctx?.logger ?? console);\n          try {\n            log?.info?.(`describeConversation session=${sessionId} chat=${described.conversationKey} sender=${described.senderId ?? '-'}`);\n          } catch {\n            // Logging must never break the lookup.\n          }\n        }\n        return described;\n      };\n      if (typeof ctx?.provide === 'function') {\n        ctx.provide('dshIm', Object.freeze({\n          contractVersion: 1,\n          receiptVersion: 1,\n          inboundVersion: 1,\n          consumeInbound: (botId, options) => deliveryService.consumeInbound(botId, options),\n          historyChecked: (botId, route, query, options) => deliveryService.historyChecked(botId, route, query, options),\n          replyChecked: (botId, route, text, options) => deliveryService.replyChecked(botId, route, text, options),\n          describeConversation: (sessionId) => describeConversationLogged(sessionId),\n\n          // Prompt assembly is synchronous, so a caller that needs the identity\n          // before the first step cannot await the async variant.\n          describeConversationSync: (sessionId) => deliveryService.describeConversationSync(sessionId),\n          describeBot: (botId) => deliveryService.describeBot(botId),\n          sendChecked: (botId, targetId, text, options) => deliveryService.sendChecked(botId, targetId, text, options),\n          send: (botId, targetId, text, options) => (\n            deliveryService.send(botId, targetId, text, options)\n          ),\n          listTargets: async (botId) => (await deliveryService.listTargets(botId)).targets,\n          createTarget: (botId, target) => deliveryService.createTarget(botId, target),\n          listBots: () => deliveryService.listBots(),\n        }));\n      }\n      const activate = async (readyCtx) => {\n        await activateChannels(readyCtx, config, deliveryService);\n      };\n      if (typeof ctx?.inject === 'function') {\n        await ctx.inject(\n          ['sessionController', 'workspaceController'],\n          activate,\n        );\n        ctx.inject(['webServer'], (httpCtx) => {\n          startDeliveryHttp(httpCtx, deliveryService);\n        });\n        return;\n      }\n      await activate(ctx);\n      if (ctx?.webServer?.register && typeof ctx?.effect === 'function') {\n        startDeliveryHttp(ctx, deliveryService);\n      }\n    },\n  });\n\n  async function activateChannels(ctx, config, deliveryService) {\n    // Bind the bot message language before any channel connects, so the first\n    // command menu a platform stores is already in the interface language.\n    const hostLanguage = startHostLanguage(ctx, config);\n    await hostLanguage?.ready;\n    const startTitlePrefix = (titleCtx) => {\n      // The installer owns its cleanup through ctx.effect(). Cordis startup\n      // callbacks must not return its controller object as an effect.\n      installSessionTitlePrefix(titleCtx, {\n        logger: typeof titleCtx?.logger === 'function'\n          ? titleCtx.logger('dsh-im:session-title') : (titleCtx?.logger ?? console),\n      });\n    };\n    if (typeof ctx?.inject === 'function') {\n      ctx.inject(['sessions'], startTitlePrefix);\n    } else if (ctx?.sessions && typeof ctx.on === 'function') {\n      startTitlePrefix(ctx);\n    }\n    if (typeof ctx?.inject === 'function') {\n      ctx.inject(['tools', 'systemPrompt'], (artifactCtx) => {\n        installOutboundArtifactTool(artifactCtx);\n        installGroupHistoryTools(artifactCtx);\n      });\n    } else {\n      installOutboundArtifactTool(ctx);\n      installGroupHistoryTools(ctx);\n    }\n    const logger = typeof ctx?.logger === 'function'\n      ? ctx.logger(name)\n      : (ctx?.logger ?? console);\n    try {\n      startInjectedContext(ctx, { logger });\n    } catch (error) {\n      logger.error?.('[dsh-im] failed to activate injected-context pairing; prompts keep the inline prefix', error);\n    }\n    if (ctx?.connection?.fetch) {\n      if (hostLanguage) {\n        try {\n          startHostLanguageRpc(ctx, hostLanguage, config.rpcAuthority);\n        } catch (error) {\n          logger.error?.('[dsh-im] failed to activate interface language mirroring; continuing with channels', error);\n        }\n      }\n      try {\n        startUpdate(ctx, { authority: config.rpcAuthority });\n      } catch (error) {\n        logger.error?.('[dsh-im] failed to activate update management; continuing with channels', error);\n      }\n      try {\n        startSidebarSettings(ctx, { config });\n      } catch (error) {\n        logger.error?.('[dsh-im] failed to activate sidebar settings; continuing with channels', error);\n      }\n      try {\n        startInboundTtl(ctx, { config });\n        startDeliverySync(ctx, { config });\n      } catch (error) {\n        logger.error?.('[dsh-im] failed to activate inbound TTL settings; continuing with channels', error);\n      }\n      try {\n        startDelivery(ctx, deliveryService, { authority: config.rpcAuthority });\n      } catch (error) {\n        logger.error?.('[dsh-im] failed to activate delivery management; continuing with channels', error);\n      }\n      try {\n        installChannelListRpc(ctx, config.rpcAuthority, { dshHome: config.dshHome });\n      } catch (error) {\n        logger.error?.('[dsh-im] failed to activate channel list; continuing with channels', error);\n      }\n    }\n    const failures = [];\n    // Each channel mounts its management RPC before awaiting initialization.\n    // Start them together so a slow channel cannot leave later routes absent.\n    await Promise.all(channels.map(async ([channel, start]) => {\n      try {\n        await start(ctx, channelConfig(config, channel, deliveryService));\n      } catch (error) {\n        failures.push(error);\n        logger.error?.(`[dsh-im] failed to activate ${channel}; continuing with the remaining channels`, error);\n      }\n    }));\n    if (failures.length === channels.length) {\n      throw new AggregateError(failures, 'dsh-im failed to activate every channel');\n    }\n    if (typeof ctx?.on === 'function') {\n      try {\n        startSessionSync(ctx, deliveryService, {\n          logger,\n          inputScope: ctx.root ?? ctx,\n          config,\n        });\n        installDsBotQuestionSync(ctx, deliveryService, { logger });\n      } catch (error) {\n        logger.error?.('[dsh-im] failed to activate Session sync; continuing with channels', error);\n      }\n    }\n  }\n}\n\nexport async function apply(ctx, config = {}) {\n  return createImHostPlugin().apply(ctx, config);\n}\n"
    },
    {
      "path": "plugin-src/host/channels/telegram/index.mjs",
      "content": "import { createProductionController } from './production.mjs';\nimport { createTelegramRpcHandler, installTelegramRpc, TELEGRAM_RPC_CHANNEL } from './rpc.mjs';\nimport { installProductionChannel } from '../shared/startup.mjs';\n\nexport const name = 'dsh-im-telegram-host';\nexport const inject = ['connection', 'credentials', 'typertGateway'];\n\nexport async function apply(ctx, config = {}) {\n  if (config?.controller) {\n    return installTelegramRpc(ctx, config.controller, config.rpcAuthority);\n  }\n  return installProductionChannel(ctx, config, {\n    channel: 'telegram',\n    rpcChannel: TELEGRAM_RPC_CHANNEL,\n    createProduction: () => createProductionController(ctx, config, config.internals ?? {}),\n    createHandler: controller => createTelegramRpcHandler(controller),\n  });\n}\n\nexport function createTelegramHostPlugin(config) {\n  return Object.freeze({ name, inject, apply: (ctx) => apply(ctx, config) });\n}\n\nexport { createProductionController } from './production.mjs';\nexport {\n  GROUP_TRIGGERS_ENDPOINTS,\n  TELEGRAM_ENDPOINTS,\n  TELEGRAM_RPC_CHANNEL,\n  TELEGRAM_RPC_ENDPOINTS,\n  createTelegramRpcHandler,\n  installTelegramRpc,\n} from './rpc.mjs';\nexport { TelegramController } from '../../../../src/channels/telegram/telegram-controller.mjs';\nexport { TelegramRuntime } from '../../../../src/channels/telegram/telegram-runtime.mjs';\n"
    },
    {
      "path": "plugin-src/host/channels/shared/startup.mjs",
      "content": "import { registerManagementRpc } from '../../../management-rpc.mjs';\nimport { onImHostLanguageChange } from '../../../../src/channels/shared/i18n.mjs';\nimport { resolveRpcAuthority } from '../../rpc-authority.mjs';\nimport { publicChannelInitializing, publicChannelStartupError } from './startup-error.mjs';\nimport { createConnectionDiagnostics, diagnosticRpcResult } from '../../../../src/channels/shared/connection-error.mjs';\n\n/**\n * Keep a channel's platform-side command menu in the current host message\n * language. Menus are registered with the platform when a bot connects, so a\n * later language change has to re-send them; channels that publish no menu\n * expose no refresh hook and are left alone.\n */\nfunction followHostLanguage(ctx, channel, controller, logger) {\n  if (typeof controller?.refreshCommandMenus !== 'function') return;\n  const unsubscribe = onImHostLanguageChange(() => {\n    // Never run a slow or failing platform call inside the language switch:\n    // subscribers are synchronous and must not delay or break one another.\n    void Promise.resolve()\n      .then(() => controller.refreshCommandMenus())\n      .catch((error) => logger.warn?.(\n        `[dsh-im] failed to re-send the ${channel} command menu after a language change`,\n        error,\n      ));\n  });\n  ctx.effect(() => unsubscribe, `dsh-im: follow the host language for ${channel} command menus`);\n}\n\n/** Mount the native management RPC before any fallible production initialization. */\nexport async function installProductionChannel(ctx, config, {\n  channel, rpcChannel, createProduction, createHandler, reportStartupError,\n}) {\n  let startupError = publicChannelInitializing(channel);\n  let handler = async () => ({ ok: false, error: startupError });\n  const logger = typeof ctx.logger === 'function' ? ctx.logger(`dsh-im:${channel}`) : (ctx.logger ?? console);\n  const diagnostics = createConnectionDiagnostics({ channel, logger });\n  const disposeRpc = registerManagementRpc(ctx, rpcChannel, async (endpoint, payload, signal) => {\n    if (signal?.aborted) {\n      return { ok: false, error: { code: 'cancelled', message: 'The request was cancelled.', details: {} } };\n    }\n    try { return await handler(endpoint, payload, signal); }\n    catch (error) {\n      // Preserve a final Host diagnostic if an endpoint misses its own catch.\n      return diagnosticRpcResult(diagnostics, error, { ok: false, error: { code: `${channel}-operation-failed` } }, { operation: endpoint });\n    }\n  }, { authority: resolveRpcAuthority(config.rpcAuthority) });\n  let production;\n  let unregisterDelivery;\n  let closing;\n  const closeProduction = () => (closing ??= (async () => {\n    try {\n      await unregisterDelivery?.();\n    } finally {\n      await production?.close();\n    }\n  })());\n  try {\n    production = await createProduction();\n    unregisterDelivery = config.deliveryService && production.deliveryAdapter\n      ? config.deliveryService.registerAdapter(production.deliveryAdapter) : undefined;\n    const readyHandler = createHandler(production.controller);\n    ctx.effect(() => closeProduction, `dsh-im: close ${channel} connections`);\n    followHostLanguage(ctx, channel, production.controller, logger);\n    handler = readyHandler;\n  } catch (error) {\n    startupError = reportStartupError\n      ? reportStartupError(error, false)\n      : diagnostics.report(error, { operation: 'startup', stage: 'startup.load', publicError: publicChannelStartupError(channel, error) }).publicError;\n    try {\n      await closeProduction();\n    } catch (cleanupError) {\n      if (reportStartupError) reportStartupError(cleanupError, true);\n      else diagnostics.report(cleanupError, { operation: 'startup', stage: 'connection.stop', warning: true });\n    }\n  }\n  return disposeRpc;\n}\n"
    },
    {
      "path": "plugin-src/host/rpc-authority.mjs",
      "content": "const RPC_AUTHORITIES = new Set(['loopback', 'trusted-host']);\n\n/**\n * Resolve the browser authority accepted by an IM management RPC channel.\n * By default, use the browser authentication and Host/Origin trust checks\n * already enforced by Harness before it dispatches a management Fetch route.\n */\nexport function resolveRpcAuthority(value) {\n  if (value === undefined) return 'trusted-host';\n  if (RPC_AUTHORITIES.has(value)) return value;\n  throw new TypeError('dsh-im rpcAuthority must be \"loopback\" or \"trusted-host\"');\n}\n"
    },
    {
      "path": "src/channels/shared/text-harness-bridge.mjs",
      "content": "import { BusyMessageDispatcher, canAutomaticallySteer } from './busy-message-dispatcher.mjs';\nimport { randomBytes, randomUUID } from 'node:crypto';\n\nimport { createDeferredDeliveryCoordinator, deferredOutcomeText } from './deferred-delivery-coordinator.mjs';\nimport { t } from './i18n.mjs';\nimport { availableCommandCatalog, commandHelpLines, SHARED_COMMAND_CATALOG } from './command-catalog.mjs';\nimport {\n  COMMAND_PERMISSION_DENIED_MESSAGE,\n  evaluateInboundAccess,\n} from './inbound-access.mjs';\nimport {\n  captureContextEnhancement,\n  captureContextEnhancementSource,\n  enhanceContextContent,\n} from './context-enhancement.mjs';\nimport { runWorkspaceCommand, workspaceSwitchFailureText } from './workspace-command.mjs';\nimport { runStatusCommand } from './status-command.mjs';\nimport { runCompactCommand } from './compact-command.mjs';\nimport { isClearCommand, runClearCommand } from './clear-command.mjs';\nimport { isResetCommand, runResetCommand } from './reset-command.mjs';\nimport { isHistoryCommand, runHistoryCommand } from './history-command.mjs';\nimport {\n  isControlCommand,\n  runControlCommand,\n} from './control-command.mjs';\nimport {\n  rememberConnectionTestTarget,\n  sendRememberedConnectionTest,\n} from './connection-test.mjs';\nimport {\n  isModelCommand,\n  runModelCommand,\n} from './model-command.mjs';\nimport {\n  isPresetCommand,\n  runPresetCommand,\n} from './preset-command.mjs';\nimport { askInWorkspaceSession } from './workspace-session.mjs';\nimport { HarnessApprovalQueue, harnessApprovalDecision } from './harness-approval.mjs';\nimport {\n  BatchInputManager,\n  batchInputBusyMessage,\n  batchInputGroupUnsupportedMessage,\n  isBatchInputCommand,\n} from './batch-input.mjs';\nimport {\n  hasInboundImages,\n  imagePromptDiagnostic,\n  imagePromptUserMessage,\n} from './image-prompt.mjs';\nimport {\n  hasInboundFiles,\n  inboundFileUserMessage,\n} from './inbound-file.mjs';\nimport {\n  harnessAnswerForQuestion,\n  harnessQuestionText,\n  validHarnessQuestion,\n} from './harness-question.mjs';\nimport { deliverOutboundArtifacts } from './semantic/artifact-delivery.mjs';\nimport { prependSpeakerLabel } from './speaker-label.mjs';\nimport {\n  hasReplyReference,\n  promptContentForInboundMessage,\n} from './semantic/reply-reference.mjs';\nimport {\n  createDeliveryReceipt,\n  createTextDeliveryBlock,\n  providerMessageIdsFor,\n} from './semantic/delivery.mjs';\nimport {\n  messageFailureDiagnostic,\n  channelDeliveryFailure,\n  clearLastMessageFailure,\n  messageFailureText,\n  setLastMessageFailure,\n} from './message-failure.mjs';\nimport { logDeliveryFailure } from './delivery-failure-log.mjs';\nimport { beginStatusReaction } from './status-reaction.mjs';\nimport { startNewConversation, isNewCommand, newCommandTitle } from './new-command.mjs';\nimport {\n  isSessionNavCommand,\n  runSessionNavCommand,\n} from './session-nav-command.mjs';\nimport {\n  documentSendSupported,\n  buttonPreviewSupported,\n} from './channel-capabilities.mjs';\nimport { createActionNonce } from './action-card.mjs';\n\n/** Cap and TTL for the in-memory workspace-picker snapshots behind button presses. */\nconst MAX_WORKSPACE_CARDS = 50;\nconst WORKSPACE_CARD_TTL_MS = 60 * 60 * 1000;\nconst WORKSPACE_CARD_NONCE_BYTES = 9;\n\nconst INTERACTION_RESOLVED_TEXT = '这个问题已在其他客户端处理，无需再次回答。';\nconst FILE_ONLY_COMPLETION_TEXT = '任务已完成。';\n\n/**\n * How many times one inbound message may be re-delivered after a failed turn.\n *\n * A failure releases the message's `markSeen` so the next poll retries it, which\n * would otherwise loop forever on a mail that always fails. After this many\n * attempts the mark stays and the message is treated as handled.\n */\nconst MAX_DELIVERY_ATTEMPTS = 3;\n/** How many plain-text messages one coalescing window folds into one dispatch. */\nconst MAX_COALESCE_MEMBERS = 8;\n\nfunction cleanText(value) {\n  return typeof value === 'string' ? value.trim() : '';\n}\n\nfunction canClaimInteractionReply(message, pending, senderId) {\n  return pending.actor === senderId\n    && (message.kind !== 'group' || message.addressed === true)\n    && !hasInboundImages(message)\n    && !hasInboundFiles(message)\n    && Boolean(controlTextOf(message));\n}\n\nfunction artifactFailureText(fileName, error, descriptor) {\n  const name = String(fileName ?? t('结果文件'))\n    .replace(/[\\r\\n]+/g, ' ')\n    .trim()\n    .slice(0, 255) || t('结果文件');\n  switch (error?.code) {\n    case 'artifact-delivery-uncertain':\n      return t('结果文件「{name}」的发送结果未能确认，请先检查聊天内是否已收到，不要立即重试。', { name });\n    case 'artifact-permission-required':\n      if (descriptor?.key === 'slack') {\n        return t('结果文件「{name}」已生成，但 Slack 应用缺少 files:write 权限。请更新 Manifest、重新安装应用并重新连接机器人后重试。', { name });\n      }\n      if (descriptor?.key === 'discord') {\n        return t('结果文件「{name}」已生成，但机器人缺少 Discord 的 Send Messages、Attach Files 或 Read Message History 权限。', { name });\n      }\n      if (descriptor?.key === 'telegram') {\n        return t('结果文件「{name}」已生成，但 Telegram 不允许机器人在当前聊天发送文档，请检查聊天权限。', { name });\n      }\n      if (descriptor?.key === 'matrix') {\n        return t('结果文件「{name}」已生成，但 Matrix homeserver 拒绝了媒体上传，请检查其媒体大小限制与上传权限。', { name });\n      }\n      return t('结果文件「{name}」已生成，但当前机器人没有文件发送权限，请检查渠道权限。', { name });\n    case 'artifact-too-large':\n      return t('结果文件「{name}」超过当前渠道大小上限，未发送。', { name });\n    case 'artifact-empty':\n      return t('结果文件「{name}」为空，未发送。', { name });\n    case 'artifact-invalid':\n    case 'artifact-changed':\n    case 'artifact-unavailable':\n      return t('结果文件「{name}」暂时无法读取或准备发送，请确认文件仍可访问后重试。', { name });\n    case 'artifact-rate-limited':\n      return t('结果文件「{name}」暂时被当前渠道限流，未能发送，请稍后重试。', { name });\n    case 'artifact-provider-rejected':\n      return t('结果文件「{name}」已生成，但当前渠道拒绝了该文件或文件消息。', { name });\n    default:\n      return t('结果文件「{name}」已生成，但当前渠道暂时未能发送，请稍后重试。', { name });\n  }\n}\n\nexport function createTextBridgeStatus() {\n  return {\n    messagesReceived: 0,\n    messagesReplied: 0,\n    messagesRejected: 0,\n    lastMessageAt: null,\n    lastReplyAt: null,\n    lastRejectedAt: null,\n    lastError: null,\n    lastMessageError: null,\n    reactionsAdded: 0,\n    reactionsRemoved: 0,\n    reactionErrors: 0,\n  };\n}\n\n/**\n * The text a channel's control commands and approval decisions are parsed from.\n *\n * A channel may decorate `content` for the model — the email channel prepends\n * the mail headers so a subject line reaches the model — while `controlText`\n * keeps the undecorated body. Without this a decorated message made `/help`\n * and \"批准\" unrecognisable.\n */\nfunction controlTextOf(message) {\n  return cleanText(message?.controlText ?? message?.content);\n}\n\n/** Durable queue-entry id; the conversation key keeps ids unique across chats. */\nfunction pendingMessageId(key, messageId) {\n  return `${key}\\u0000${messageId}`;\n}\n\nconst PENDING_RESTART_NOTICE = '排队中的消息在服务重启时被中断。为避免重复执行，未自动重放；如果该消息尚未处理，请重新发送。';\n\n// Callback namespace for the /tail preview \"Hide\" button: the payload is the\n// nonce of the preview message the bot must delete when pressed.\nconst TAIL_HIDE_CALLBACK_PREFIX = 'tailhide|';\n\nexport class TextHarnessBridge {\n  #descriptor;\n  #bot;\n  #harness;\n  #state;\n  #deferred;\n  #contextEnhancement;\n  #accessPolicy;\n  #thinkingTraces;\n  #status;\n  #logger;\n  #replyTimeoutMs;\n  #signal;\n  #keepaliveIntervalMs;\n  #queues = new Map();\n  // Crash-recovery for #queues, started with the bridge; see recoverPendingMessages().\n  #pendingRecovery = null;\n  #busyMessages = new BusyMessageDispatcher();\n  #pendingInteractions = new Map();\n  #interactionKeys = new Map();\n  // Keep the accepted configuration through the existing queue/reply lifecycle.\n  #acceptedMessageIds = new Map();\n  #approvalTasks = new Set();\n  #commandTasks = new Set();\n  #approvals;\n  #batches = new BatchInputManager();\n  #interactionCard;\n  #workspaceCard;\n  // Workspace picker snapshots by nonce: the press carries an index, not a path.\n  #workspaceCards = new Map();\n  // Conversation key → the one picker card that is still authoritative there.\n  #workspaceCardKeys = new Map();\n  // /tail preview messages by nonce, so the \"Hide\" press can delete the bot's\n  // own preview message. Keyed by nonce → { target, providerMessageId }.\n  #tailPreviewMessages = new Map();\n  // Optional channel-supplied approval card controller (see HarnessApprovalQueue's\n  // render hook). Null keeps every channel's existing plain-text approval flow.\n  #approvalCard;\n  #contextHooks = null;\n  // Delivery attempts per message id. A failed turn releases its `markSeen` so\n  // the next poll can retry, and this counter is what keeps that from becoming\n  // an infinite loop on a mail that always fails.\n  #deliveryAttempts = new Map();\n  // Who opened the in-flight turn per conversation key, for the same-sender\n  // auto-steer lane; and the open coalescing windows awaiting their flush.\n  #turnAuthors = new Map();\n  #coalescing = new Map();\n  #autoSteerSameSender = false;\n  #autoSteerLimit = 0;\n  #coalesceWindowMs = 0;\n\n  constructor({\n    descriptor,\n    bot,\n    harness,\n    state,\n    contextEnhancement,\n    accessPolicy,\n    thinkingTraces = false,\n    status = createTextBridgeStatus(),\n    logger = console,\n    replyTimeoutMs = 600_000,\n    signal,\n    keepaliveIntervalMs = 4_000,\n    interactionCard = null,\n    workspaceCard = null,\n    approvalCard = null,\n    approvalTimeoutMs,\n    contextHooks = null,\n    autoSteerSameSender = false,\n    autoSteerLimit = 0,\n    coalesceWindowMs = 0,\n  }) {\n    if (!descriptor?.key || !descriptor?.label) throw new TypeError('A channel descriptor is required');\n    if (!bot || typeof bot.sendText !== 'function') throw new TypeError('A bot client is required');\n    if (!harness || !state) throw new TypeError('Harness client and state store are required');\n    this.#descriptor = descriptor;\n    this.#bot = bot;\n    this.#harness = harness;\n    this.#state = state;\n    this.#contextEnhancement = contextEnhancement;\n    this.#accessPolicy = accessPolicy;\n    this.#thinkingTraces = thinkingTraces;\n    this.#status = status;\n    this.#logger = logger;\n    this.#replyTimeoutMs = replyTimeoutMs;\n    this.#signal = signal;\n    this.#keepaliveIntervalMs = keepaliveIntervalMs;\n    this.#interactionCard = interactionCard ?? null;\n    this.#workspaceCard = workspaceCard ?? null;\n    this.#approvalCard = approvalCard ?? null;\n    // Opt-in follow-up lanes for channels whose groups run on rapid consecutive\n    // posts: fold a same sender's burst into one dispatch, and steer that\n    // sender's own mid-turn follow-ups into the in-flight turn instead of\n    // queueing them behind the answer they are meant to correct. Off unless a\n    // channel asks for them, so every other channel keeps the plain queue.\n    this.#autoSteerSameSender = autoSteerSameSender === true;\n    this.#autoSteerLimit = Number.isSafeInteger(autoSteerLimit) && autoSteerLimit > 0\n      ? Math.min(autoSteerLimit, 20)\n      : 0;\n    this.#coalesceWindowMs = Number.isSafeInteger(coalesceWindowMs) && coalesceWindowMs > 0\n      ? Math.min(coalesceWindowMs, 3_000)\n      : 0;\n    // Channel-supplied conversation context pipeline (collect/render/consume/deliver).\n    // Channels own what context means and how it is framed; the bridge only runs\n    // the steps at the right points of one turn, so every hook is optional and a\n    // channel without one pays no context work at all.\n    this.#contextHooks = contextHooks && typeof contextHooks === 'object' ? contextHooks : null;\n    this.#deferred = createDeferredDeliveryCoordinator({ harness, state, signal, logger,\n      deliver: (entry, outcome) => this.#deliverDeferredOutcome(entry, outcome),\n    });\n    this.#approvals = new HarnessApprovalQueue({\n      label: descriptor.key,\n      logger,\n      // Tests and hosts may shorten the approval deadline; the default stays.\n      ...(Number.isFinite(approvalTimeoutMs) && approvalTimeoutMs > 0\n        ? { approvalTimeoutMs }\n        : {}),\n    });\n    // A queued message lives only in #queues. If the process dies before its\n    // turn runs the user has already been told it is queued, so the persisted\n    // entry must be replayed or reported as soon as the bridge starts.\n    this.recoverPendingMessages();\n  }\n\n  get status() {\n    return structuredClone(this.#status);\n  }\n\n  accept(message, { contextSnapshot, accessDecision, busyMessageMode } = {}) {\n    if (this.#signal?.aborted) return Promise.resolve();\n    const conversationId = cleanText(message?.conversationId);\n    const kind = message?.kind === 'group' ? 'group' : 'direct';\n    const normalized = { ...message, kind, conversationId };\n    const messageId = cleanText(normalized.messageId);\n    const senderId = cleanText(normalized.senderId);\n    if (!messageId || !senderId || !conversationId || normalized.senderIsBot === true\n      || this.#state.hasSeen(messageId) || this.#acceptedMessageIds.has(messageId)) {\n      return Promise.resolve();\n    }\n    // Preserve the channel trigger boundary. Access policy never turns an\n    // unaddressed group message into a denial reply.\n    if (kind === 'group' && normalized.addressed !== true) {\n      this.#status.messagesRejected += 1;\n      this.#status.lastRejectedAt = new Date().toISOString();\n      this.#acceptedMessageIds.set(messageId, null);\n      return this.#finishLocalMessage(normalized, messageId, null);\n    }\n    if (this.#accessPolicy || accessDecision) {\n      const hasImages = hasInboundImages(normalized);\n      const hasFiles = hasInboundFiles(normalized);\n      const decision = accessDecision ?? evaluateInboundAccess(this.#accessPolicy, {\n        conversationType: kind,\n        senderIds: [senderId, cleanText(normalized.senderAlternateId)].filter(Boolean),\n        // The same control text the command runner below parses. A channel may\n        // decorate `content` for the model (email prepends the mail headers), and\n        // a decorated body never looks like a command — so reading `content` here\n        // recognized no command at all and skipped the command-permission gate.\n        text: controlTextOf(normalized),\n        hasImages,\n        hasFiles,\n      });\n      if (!decision.allowed) {\n        this.#status.messagesRejected += 1;\n        this.#status.lastRejectedAt = new Date().toISOString();\n        // Mark policy denials so a webhook replay cannot repeat local work or\n        // a command-permission notice.\n        this.#acceptedMessageIds.set(messageId, null);\n        return this.#finishLocalMessage(\n          normalized,\n          messageId,\n          decision.reason === 'command-not-allowed'\n            ? t(COMMAND_PERMISSION_DENIED_MESSAGE)\n            : null,\n          { recordReceived: decision.reason === 'command-not-allowed' },\n        );\n      }\n    }\n    this.#acceptedMessageIds.set(messageId, contextSnapshot === undefined\n      ? captureContextEnhancement(this.#contextEnhancement, message?.kind)\n      : contextSnapshot);\n    const statusReaction = beginStatusReaction({\n      adapter: this.#bot,\n      target: normalized.kind === 'direct' || normalized.addressed === true\n        ? normalized.reactionTarget\n        : null,\n      reactions: this.#descriptor.reactions,\n      status: this.#status,\n      logger: this.#logger,\n      label: this.#descriptor.key,\n    });\n    normalized.statusReaction = statusReaction;\n\n    const processing = this.#acceptAcceptedMessage(normalized, messageId, senderId, busyMessageMode);\n    void processing.then(\n      () => statusReaction.success(),\n      () => statusReaction.error(),\n    );\n    return processing;\n  }\n\n  #acceptAcceptedMessage(normalized, messageId, senderId, busyMessageMode) {\n    if (normalized.kind === 'direct') {\n      rememberConnectionTestTarget(\n        this.#state,\n        normalized.connectionTestTarget ?? normalized.replyTarget,\n      );\n    }\n\n    const key = `${normalized.kind}:${normalized.conversationId}`;\n    const pending = this.#pendingInteractions.get(key);\n    const text = controlTextOf(normalized);\n    if (isClearCommand(text) && (\n      this.#queues.has(key)\n      || pending\n      || this.#approvals.hasPending(key)\n      || this.#batches.status(key).phase !== 'idle'\n    )) {\n      return this.#finishLocalMessage(\n        normalized,\n        messageId,\n        t('当前会话正在生成回复或等待交互，请先完成交互或发送 /stop，再执行 /clear。'),\n      );\n    }\n    const batchCommand = isBatchInputCommand(text);\n    if (batchCommand && normalized.kind === 'group' && normalized.addressed === true) {\n      return this.#finishLocalMessage(\n        normalized,\n        messageId,\n        batchInputGroupUnsupportedMessage(),\n      );\n    }\n    if (batchCommand && normalized.kind === 'direct') {\n      const exactBatch = /^\\/batch$/iu.test(text);\n      if (exactBatch && (\n        this.#queues.has(key)\n        || Boolean(pending)\n        || this.#approvals.hasPending(key)\n      )) {\n        return this.#finishLocalMessage(normalized, messageId, batchInputBusyMessage());\n      }\n      const batch = this.#batches.handle(key, text, {\n        plainText: Boolean(text)\n          && normalized.plainText !== false\n          && !hasInboundImages(normalized)\n          && !hasInboundFiles(normalized)\n          && !hasReplyReference(normalized),\n      });\n      if (batch.handled) {\n        if (batch.kind === 'submit') {\n          return this.#enqueueMessage({\n            ...normalized,\n            content: batch.prompt,\n            // The submission is exactly the collected text; a quote or an\n            // attachment on the command itself is not part of it.\n            replyTo: null,\n            images: [],\n            files: [],\n            batchSubmission: { token: batch.token, title: batch.title },\n          }, messageId, senderId, key);\n        }\n        return this.#finishLocalMessage(normalized, messageId, batch.message);\n      }\n    } else if (normalized.kind === 'direct'\n      && this.#batches.status(key).phase === 'collecting') {\n      const batch = this.#batches.handle(key, text, {\n        plainText: Boolean(text)\n          && normalized.plainText !== false\n          && !hasInboundImages(normalized)\n          && !hasInboundFiles(normalized)\n          && !hasReplyReference(normalized),\n      });\n      if (batch.handled) {\n        return this.#finishLocalMessage(normalized, messageId, batch.message);\n      }\n    }\n    const collectingBatch = normalized.kind === 'direct'\n      && this.#batches.status(key).phase === 'collecting';\n    const commandRunner = collectingBatch ? null : isClearCommand(text) ? runClearCommand\n      : isResetCommand(text) ? runResetCommand\n      : isHistoryCommand(text) ? runHistoryCommand\n      : hasInboundFiles(normalized) ? null : isControlCommand(text)\n      ? runControlCommand\n      : (isModelCommand(text)\n          ? runModelCommand\n          : (isPresetCommand(text) ? runPresetCommand : null));\n    if (commandRunner && (normalized.kind !== 'group' || normalized.addressed === true)) {\n      let task;\n      task = this.#processFastCommand(\n        normalized,\n        messageId,\n        key,\n        commandRunner,\n        senderId,\n      ).finally(() => {\n        this.#acceptedMessageIds.delete(messageId);\n        this.#commandTasks.delete(task);\n      });\n      this.#commandTasks.add(task);\n      return task;\n    }\n    // An addressed plain-text request that is no approve/reject token while only\n    // an approval waits is the sender moving on, not a decision: reject the\n    // waiting tool call and run this message as its own turn, so the room is not\n    // held behind a decision that is not coming. A pending question keeps its\n    // ordinary flow — the asking actor's @ text answers it, and other senders\n    // queue behind the turn (questions belong to the asking actor). Direct chats\n    // keep the plain decide-by-token path; their exits are the commands.\n    const addressedTrigger = normalized.kind === 'group' && normalized.addressed === true\n      && normalized.plainText !== false\n      && !hasInboundImages(normalized) && !hasInboundFiles(normalized)\n      && Boolean(text);\n    if (addressedTrigger && !pending\n      && this.#approvals.hasPending(key) && harnessApprovalDecision(text) === null) {\n      let task;\n      task = this.#retireWaitingInteractions(key, pending)\n        .then(() => this.#bot.sendText(normalized.replyTarget, t('已不再等待原有的待回答或待审批，已将其取消，先回应你的新请求。')))\n        .catch(() => undefined)\n        .then(() => this.#dispatchTrigger(normalized, messageId, senderId, key))\n        .finally(() => {\n          this.#acceptedMessageIds.delete(messageId);\n          this.#commandTasks.delete(task);\n        });\n      this.#commandTasks.add(task);\n      return task;\n    }\n    const approval = this.#approvals.claimReply({\n      key,\n      actor: senderId,\n      messageId,\n      // Approval decisions are parsed from the control text, exactly like the\n      // commands above: a decorated `content` hid \"批准\" behind the mail headers,\n      // so a plain-body approval never claimed its pending request.\n      text: hasInboundImages(normalized) || hasInboundFiles(normalized)\n        ? ''\n        : controlTextOf(normalized),\n      addressed: normalized.kind !== 'group' || normalized.addressed === true,\n      hasPendingQuestion: Boolean(pending),\n      questionCompletion: pending?.submitting || pending?.claimedReplyMessageId\n        ? pending.queue\n        : null,\n      isQuestionPending: () => this.#pendingInteractions.has(key),\n      send: (text) => this.#bot.sendText(normalized.replyTarget, text),\n    });\n    if (approval) {\n      let task;\n      task = approval.process(async () => {\n          if (this.#state.hasSeen(messageId)) return false;\n          await this.#state.markSeen(messageId);\n          this.#status.messagesReceived += 1;\n          this.#status.lastMessageAt = new Date().toISOString();\n          return true;\n        })\n        .finally(() => {\n          this.#acceptedMessageIds.delete(messageId);\n          this.#approvalTasks.delete(task);\n        });\n      this.#approvalTasks.add(task);\n      return task;\n    }\n    if (pending && pending.actor !== senderId) {\n      return this.#enqueueMessage(normalized, messageId, senderId, key);\n    }\n    if (pending?.submitting || pending?.claimedReplyMessageId) {\n      return this.#enqueueMessage(normalized, messageId, senderId, key);\n    }\n    if (pending) {\n      if (canClaimInteractionReply(normalized, pending, senderId)) {\n        pending.claimedReplyMessageId = messageId;\n      }\n      const previous = pending.queue ?? Promise.resolve();\n      const current = previous\n        .catch(() => undefined)\n        .then(() => this.#processInteractionReply(\n          normalized,\n          messageId,\n          senderId,\n          key,\n          pending,\n        ))\n        .finally(() => {\n          this.#acceptedMessageIds.delete(messageId);\n          if (pending.claimedReplyMessageId === messageId) {\n            pending.claimedReplyMessageId = null;\n          }\n          if (pending.queue === current) pending.queue = null;\n        });\n      pending.queue = current;\n      return current;\n    }\n    return this.#dispatchTrigger(normalized, messageId, senderId, key, {\n      // Ordinary destinations of the lanes fall through to the busy-mode dispatcher,\n      // keeping its steering, receipts, and routing serialization for what the lanes decline.\n      exit: (exitOptions) => this.#busyMessages.dispatch({\n        key, messageId, text: normalized.content,\n        commandText: text, mode: busyMessageMode,\n        onFailure: (error) => this.#signal?.aborted || error?.code === 'turn-stopped'\n          ? normalized.statusReaction?.clear() : normalized.statusReaction?.error(),\n        eligible: () => normalized.plainText !== false\n          && !hasInboundImages(normalized) && !hasInboundFiles(normalized)\n          && !hasReplyReference(normalized)\n          && canAutomaticallySteer(this.#accessPolicy, normalized.kind,\n            [senderId, normalized.senderAlternateId].filter(Boolean)),\n        harness: this.#harness, state: this.#state, status: this.#status,\n        signal: this.#signal, control: { owner: this, key }, logger: this.#logger,\n        acceptedMessageIds: this.#acceptedMessageIds,\n        pendingInteraction: () => this.#pendingInteractions.has(key) || this.#approvals.hasPending(key),\n        enhancement: {\n          snapshot: this.#acceptedMessageIds.get(messageId),\n          source: () => {\n            const source = normalized.contextSource?.();\n            return { channel: this.#descriptor.key, senderId, senderName: source?.senderName,\n              conversationTitle: source?.conversationTitle,\n              chatId: source?.chatId ?? normalized.conversationId, threadId: source?.threadId };\n          },\n        },\n        isQueued: () => this.#queues.has(key),\n        enqueue: (enqueueOptions) => this.#enqueueMessage(normalized, messageId, senderId, key, enqueueOptions),\n        send: (reply) => this.#bot.sendText(normalized.replyTarget, reply),\n      }),\n    });\n  }\n\n  /**\n   * The ordinary trigger exit, where a message becomes a turn. Three lanes:\n   * while the conversation runs, a plain-text follow-up from the very sender\n   * who opened the in-flight turn steers that turn (the room hears the\n   * correction at the next model step instead of after the whole answer);\n   * on an idle conversation, consecutive plain-text posts from one sender fold\n   * into a single dispatch inside a short window, so a burst split across\n   * bubbles becomes one turn;